fn count_letters(text: &String) -> usize {
    text.len()   // len counts bytes: one per letter in plain English text
}

fn main() {
    let word = String::from("borrow");
    let n = count_letters(&word);
    println!("{word} has {n} letters");
}

fn main() {
    let city = String::from("Hanoi");
    let r1 = &city;
    let r2 = &city;
    println!("{r1} {r2} {city}");
}

