fn total_length(x: String, y: String) -> usize {
    x.len() + y.len()
}

fn main() {
    let a = String::from("good");
    let b = String::from("night");
    println!("{}", total_length(a, b));
    println!("{a}");
}

exercise.solution:
fn total_length(x: &String, y: &String) -> usize {
    x.len() + y.len()
}

fn main() {
    let a = String::from("good");
    let b = String::from("night");
    println!("{}", total_length(&a, &b));
    println!("{a}");
}
